function showTab(name, btn) {
  document.querySelectorAll('.tab-section').forEach(s =>
    s.classList.remove('active')
  );
  document.querySelectorAll('nav button').forEach(b =>
    b.classList.remove('active')
  );
  var el = document.getElementById('tab-' + name);
  if (el) el.classList.add('active');
  btn.classList.add('active');
  const hero = document.getElementById('home-hero');
  if (hero) {
hero.style.display = name === 'about' ? 'grid' : 'none';  }
  window.scrollTo(0, 0);
}

function showPage(id) {
  document.querySelectorAll('.tab-section').forEach(s => s.classList.remove('active'));
  document.querySelectorAll('nav button').forEach(b => b.classList.remove('active'));
  var el = document.getElementById(id) || document.getElementById('tab-' + id);
  if (el) el.classList.add('active');
  const hero = document.getElementById('home-hero');
if (hero) {
  hero.style.display = 'none';
}
  window.scrollTo(0, 0);
}

function showPageBack(id) {
  document.querySelectorAll('.tab-section').forEach(s => s.classList.remove('active'));
  document.querySelectorAll('nav button').forEach(b => b.classList.remove('active'));
  var el = document.getElementById('tab-' + id);
  if (el) el.classList.add('active');
  // highlight the matching nav button
  document.querySelectorAll('nav button').forEach(function(b) {
    if (b.getAttribute('onclick') && b.getAttribute('onclick').indexOf("'" + id + "'") > -1) {
      b.classList.add('active');
    }
  });
  const hero = document.getElementById('home-hero');
if (hero) {
  hero.style.display = name === 'about' ? 'flex' : 'none';
}
  window.scrollTo(0, 0);
}

function switchSubpane(prefix, pane, btn) {
  var page = btn.closest('.proj-page');
  if (!page) return;
  page.querySelectorAll('.proj-subtab-btn').forEach(function(b) { b.classList.remove('active'); });
  page.querySelectorAll('.proj-subpane').forEach(function(p) { p.classList.remove('active'); });
  btn.classList.add('active');
  var el = document.getElementById(prefix + '-' + pane);
  if (el) el.classList.add('active');
}

function switchAdvisor(key, btn) {
  var page = btn.closest('.proj-page');
  if (!page) page = document.body;
  page.querySelectorAll('.advisor-pane').forEach(function(p) { p.classList.remove('active'); });
  page.querySelectorAll('.advisor-tab-btn').forEach(function(b) { b.classList.remove('active'); });
  btn.classList.add('active');
  var el = document.getElementById('ap-' + key);
  if (el) el.classList.add('active');
}


/* Imported AACOM Projects scripts */
function showSubPage(pageId, subId) {
  var page = document.getElementById(pageId) || document.getElementById('tab-' + pageId) || document.getElementById('page-' + pageId);
  if (!page) return;
  page.querySelectorAll('.sub-page').forEach(function(sp) { sp.classList.remove('active'); });
  page.querySelectorAll('.sec-tab').forEach(function(t) { t.classList.remove('active'); });
  var target = document.getElementById(pageId + '-' + subId);
  if (target) target.classList.add('active');
  if (window.event && window.event.target) window.event.target.classList.add('active');
}




function handleGraphicFile(file, imgId, nameId, containerId, uploadId) {
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    document.getElementById(imgId).src = e.target.result;
    document.getElementById(nameId).textContent = '🖼️ ' + file.name;
    // set download link
    const dlId = imgId.replace('-img', '-dl');
    const dlEl = document.getElementById(dlId);
    if (dlEl) { dlEl.href = e.target.result; dlEl.setAttribute('download', file.name); }
    document.getElementById(uploadId).style.display = 'none';
    document.getElementById(containerId).style.display = 'block';
  };
  reader.readAsDataURL(file);
}
function handleGraphicDrop(event, inputId, imgId, nameId, containerId, uploadId) {
  event.preventDefault();
  const file = event.dataTransfer.files[0];
  if (file) handleGraphicFile(file, imgId, nameId, containerId, uploadId);
}
function clearGraphic(imgId, nameId, containerId, uploadId, inputId, dlId) {
  document.getElementById(imgId).src = '';
  document.getElementById(containerId).style.display = 'none';
  document.getElementById(uploadId).style.display = 'block';
  document.getElementById(inputId).value = '';
}




function toggleAccordion(el) {
  const header = el.querySelector('.accordion-header');
  const body = el.querySelector('.accordion-body');
  const isOpen = header.classList.contains('open');
  // close all in same parent
  const parent = el.parentElement;
  parent.querySelectorAll('.accordion-header').forEach(h => h.classList.remove('open'));
  parent.querySelectorAll('.accordion-body').forEach(b => b.classList.remove('open'));
  if (!isOpen) {
    header.classList.add('open');
    body.classList.add('open');
  }
}



// ── Auto-embed all uploaded assets ──
(function() {
  // Helper: show a PDF iframe container
  function showPdf(frameId, uploadId, containerId, nameId, uri, filename) {
    document.getElementById(frameId).src = uri;
    if (nameId) document.getElementById(nameId).textContent = '📎 ' + filename;
    document.getElementById(uploadId).style.display = 'none';
    var c = document.getElementById(containerId);
    c.style.display = 'flex';
    c.style.flexDirection = 'column';
  }
  // Helper: show image
  function showImg(imgId, uploadId, containerId, nameId, dlId, uri, filename) {
    document.getElementById(imgId).src = uri;
    if (nameId) document.getElementById(nameId).textContent = '🖼️ ' + filename;
    if (dlId) { document.getElementById(dlId).href = uri; document.getElementById(dlId).setAttribute('download', filename); }
    document.getElementById(uploadId).style.display = 'none';
    document.getElementById(containerId).style.display = 'block';
  }
  // Helper: show PDF with simple container (non-flex)
  function showPdfSimple(frameId, uploadId, containerId, nameId, dlId, uri, filename) {
    document.getElementById(frameId).src = uri;
    if (nameId) document.getElementById(nameId).textContent = '📎 ' + filename;
    if (dlId) { document.getElementById(dlId).href = uri; document.getElementById(dlId).setAttribute('download', filename); }
    document.getElementById(uploadId).style.display = 'none';
    document.getElementById(containerId).style.display = 'block';
  }


  // 2.  page
  var aacomasUri = "data:application/pdf;base64,";
  document.getElementById('aacomas-pdf-frame').src = aacomasUri;
  document.getElementById('aacomas-pdf-name').textContent = '📎 AACOMAS_101.pdf';
  document.getElementById('aacomas-upload-area').style.display = 'none';
  document.getElementById('aacomas-pdf-container').style.display = 'block';

  // 3. Dual Boards — PDF1: Infographic
  var boardsInfographic = "data:application/pdf;base64,";
  showPdf('boards-pdf-frame','boards-pdf-upload','boards-pdf-container','boards-pdf-name', boardsInfographic, 'COMLEX_vs_USMLE_Infographic.pdf');

  // 4. Dual Boards — PNG: Cartoon
  var boardsCartoon = "data:image/png;base64,";
  showImg('boards-png-img','boards-png-upload','boards-png-container','boards-png-name', null, boardsCartoon, 'COMLEX_vs_USMLE_cartoon.png');

  // 5. Dual Boards — PDF3: Impact paper
  var boardsImpact = "data:application/pdf;base64,";
  showPdf('boards-pdf3-frame','boards-pdf3-upload','boards-pdf3-container','boards-pdf3-name', boardsImpact, 'Impact_of_Dual_Board_Exams.pdf');

  // 6. Graphics — Graphic 1: Tenets PDF → show as embedded PDF via object
  // We'll use graphic1 img slot but swap to an iframe approach since it's a PDF
  // Actually graphic1 is an img slot — put specialty PNG there, tenets in graphic2 as download
  var specialtyUri = "data:image/png;base64,";
  showImg('graphic1-img','graphic1-upload','graphic1-container','graphic1-name','graphic1-dl', specialtyUri, 'Specialty_options_vertical.png');

  // 7. Graphics — Graphic 2: Tenets — PDF, so we need to handle differently
  // Replace graphic2 img with an iframe for the PDF
  var tenetsUri = "data:application/pdf;base64,";
  var g2upload = document.getElementById('graphic2-upload');
  var g2container = document.getElementById('graphic2-container');
  var g2name = document.getElementById('graphic2-name');
  var g2dl = document.getElementById('graphic2-dl');
  // Swap img for iframe
  var g2img = document.getElementById('graphic2-img');
  var iframe = document.createElement('iframe');
  iframe.src = tenetsUri;
  iframe.style.cssText = 'width:100%;height:500px;border-radius:8px;border:1px solid var(--border);display:block;';
  g2img.parentNode.replaceChild(iframe, g2img);
  if (g2name) g2name.textContent = '📎 Tenets_of_Osteopathic_Medicine.pdf';
  if (g2dl) { g2dl.href = tenetsUri; g2dl.setAttribute('download', 'Tenets_of_Osteopathic_Medicine.pdf'); }
  g2upload.style.display = 'none';
  g2container.style.display = 'block';
  document.addEventListener('DOMContentLoaded', function () {
  const hero = document.getElementById('home-hero');
  const about = document.getElementById('tab-about');

  if (hero && about && about.classList.contains('active')) {
    hero.style.display = 'flex';
  }
});
})();